def move_one_ball(arr):
    if len(arr) <= 1:
        return True

    # Find the index where arr[i] > arr[i+1], which indicates a potential rotation point
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            break
    else:
        # If no such point is found, array is already sorted
        return True

    pivot = i

    # Check if the rotated part from pivot to end is non-decreasing
    for j in range(pivot + 1, len(arr)):
        if arr[j] < arr[j - 1]:
            return False

    # Check if the first element (after rotation) <= last element of original array
    if arr[0] > arr[-1]:
        return False

    return True

